"use strict";

const fs = require("fs");

/**
 * WorkState tracks the set of work needed to be accomplished
 * in apply-update. It is an ordered list of work items, with each
 * item containing:
 * {
 *     source: string,      // path to source file for this update
 *     subsystem: string,   // subsystem for this update
 *     step: string,        // current step in the update process, one of: null, "init", "unpack", "verify", "retry"
 *     from: string,        // version we are updating from    
 *     to: string,          // version we are updating to
 *     size: int            // size (bytes) of the source file
 *     filter: string       // filter to use when checking for updates
 * }
 *
 */

function WorkState() {
    this.idx = null;
    this.items = [];
};

WorkState.prototype = {
    constructor: WorkState,
    addItem: function(item) {
        this.items.push(item);
        if (this.idx === null) {
            this.idx = 0;
        }
    },
    load: function(filename, callback) {
        fs.readFile(filename, function(error, data) {
            if (error) {
                if (typeof(callback) == "function") {
                    callback(error);
                }
                return;
            }
            let parsed = JSON.parse(data);
            this.idx = data.idx;
            this.items = data.items;
            if (typeof(callback) == "function") {
                callback(null);
            }
        });
    },
    loadSync: function(filename) {
        let data = JSON.parse(fs.readFileSync(filename));
        this.idx = data.idx;
        this.items = data.items;
    },
    save: function(filename, callback) {
        fs.writeFile(filename, JSON.stringify(this), function(error) {
            if (typeof(callback) == "function") {
                callback(error);
            }
        });
    },
    saveSync: function(filename) {
        fs.writeFileSync(filename, JSON.stringify(this));
    },
    current: function() {
        if (this.idx !== null) {
            return this.items[this.idx];
        }
        return null;
    },
    finishCurrent: function() {
        this.idx += 1;
        if (this.idx >= this.items.length) {
            this.idx = null;
        }
    },
    moreUpdates: function() {
        return this.idx < (this.items.length-1);
    },
    pendingUpdateFor: function(subsystem) {
        for (let i=this.idx; i<this.items.length; ++i) {
            if (this.items[i].subsystem == subsystem) {
                return true;
            }
        }
        return false;
    },
    retryAll: function() {
        if (this.items.length > 0) {
            for (let i=0; i<this.items.length; ++i) {
                this.items[i].step = "retry";
            }
            this.idx = 0;
        }
    }
};

module.exports = {
    WorkState: WorkState
};
